def _detect_line_ending(source: IO[str]) -> str:
    """Detect the first LF or CRLF line-ending style in the stream.

    Returns "\r\n" if the first line ending is CRLF, "\n" if it is LF, or
    "\n" when no line ending is present. The stream position is restored to
    its original value.
    """
    start = source.tell()
    try:
        content = source.read()
    finally:
        source.seek(start)
    if "\r\n" in content:
        return "\r\n"
    if "\n" in content:
        return "\n"
    return "\n"


@contextmanager
def rewrite(
    path: StrPath,
    encoding: Optional[str],
) -> Iterator[Tuple[IO[str], IO[str]]]:
    pathlib.Path(path).touch()

    with tempfile.NamedTemporaryFile(mode="w", encoding=encoding, delete=False) as dest:
        error = None
        try:
            with open(path, encoding=encoding) as source:
                yield (source, dest)
        except BaseException as err:
            error = err

    if error is None:
        shutil.move(dest.name, path)
    else:
        os.unlink(dest.name)
        raise error from None

